package com.tnc.tnc.life.routes;
import net.minecraft.world.item.*;
/** A wearable armor item: the powered pack is visible on the player. */
public final class RouteMechItem extends ArmorItem implements ManaCharged {
    public RouteMechItem(){super(ArmorMaterials.NETHERITE,Type.CHESTPLATE,new Properties().stacksTo(1).durability(4096).fireResistant());}
    public int manaCapacity(){return com.tnc.tnc.life.routes.mech.MechRules.CAPACITY;}
    @Override public String getArmorTexture(ItemStack stack,net.minecraft.world.entity.Entity entity,net.minecraft.world.entity.EquipmentSlot slot,String type){return "tnc:textures/models/armor/mana_mech_layer_1.png";}
    @Override public void inventoryTick(ItemStack stack,net.minecraft.world.level.Level l,net.minecraft.world.entity.Entity holder,int slot,boolean selected){if(holder instanceof net.minecraft.server.level.ServerPlayer p)com.tnc.tnc.life.routes.mech.MechCombat.tick(p,stack);}
    @Override public void appendHoverText(ItemStack stack,net.minecraft.world.level.Level l,java.util.List<net.minecraft.network.chat.Component> out,TooltipFlag flags){out.add(net.minecraft.network.chat.Component.literal("天穹式 · 储魔 "+(stack.hasTag()?stack.getTag().getInt("ChargedMana"):0)+"/12000 · 充能台最高128M/秒"));out.add(net.minecraft.network.chat.Component.literal("六联晶铳长按连射；潜行右键切元素。V推进 / 潜行V震荡 / B屏障 / G过载（可改键）"));}
    @Override public com.google.common.collect.Multimap<net.minecraft.world.entity.ai.attributes.Attribute,net.minecraft.world.entity.ai.attributes.AttributeModifier> getDefaultAttributeModifiers(net.minecraft.world.entity.EquipmentSlot slot){if(slot!=net.minecraft.world.entity.EquipmentSlot.CHEST)return super.getDefaultAttributeModifiers(slot);var b=com.google.common.collect.ImmutableMultimap.<net.minecraft.world.entity.ai.attributes.Attribute,net.minecraft.world.entity.ai.attributes.AttributeModifier>builder();var id=java.util.UUID.fromString("44a55112-3322-4411-8888-111122223333");b.put(net.minecraft.world.entity.ai.attributes.Attributes.ARMOR,new net.minecraft.world.entity.ai.attributes.AttributeModifier(id,"Skyward armor",18,net.minecraft.world.entity.ai.attributes.AttributeModifier.Operation.ADDITION));b.put(net.minecraft.world.entity.ai.attributes.Attributes.ARMOR_TOUGHNESS,new net.minecraft.world.entity.ai.attributes.AttributeModifier(id,"Skyward toughness",6,net.minecraft.world.entity.ai.attributes.AttributeModifier.Operation.ADDITION));b.put(net.minecraft.world.entity.ai.attributes.Attributes.KNOCKBACK_RESISTANCE,new net.minecraft.world.entity.ai.attributes.AttributeModifier(id,"Skyward anchors",.35,net.minecraft.world.entity.ai.attributes.AttributeModifier.Operation.ADDITION));return b.build();}
    @Override public void initializeClient(java.util.function.Consumer<net.minecraftforge.client.extensions.common.IClientItemExtensions> c){c.accept(new net.minecraftforge.client.extensions.common.IClientItemExtensions(){private com.tnc.tnc.life.routes.mech.SkywardArmorModel model;
        @Override public net.minecraft.client.model.Model getGenericArmorModel(net.minecraft.world.entity.LivingEntity entity,ItemStack stack,net.minecraft.world.entity.EquipmentSlot slot,net.minecraft.client.model.HumanoidModel<?> original){if(model==null)model=new com.tnc.tnc.life.routes.mech.SkywardArmorModel(net.minecraft.client.Minecraft.getInstance().getEntityModels().bakeLayer(RouteMechModel.LAYER));net.minecraftforge.client.ForgeHooksClient.copyModelProperties(original,model);model.setAllVisible(true);model.hat.visible=false;model.color=com.tnc.tnc.life.routes.mech.MechRules.COLORS[Math.floorMod(stack.getOrCreateTag().getInt("MechElement"),7)];return model;}
    });}
}
